let hills=[];for(let group=0;group<4;group++){let x=-42+random()*84,z=-42+random()*84;for(let attempt=0;attempt<20&&mode!==1&&Math.abs(x-line(z))<14;attempt++)x=-42+random()*84;let count=group===0?3:2;for(let j=0;j<count;j++)hills.push({x:x+(random()-.5)*9,z:z+(random()-.5)*9,rx:5+random()*5,rz:5+random()*6,height:10+random()*6,phase:random()*6.28})}let forestCenters=Array.from({length:13},()=>({x:-57+random()*114,z:-57+random()*114,rx:10+random()*8,rz:9+random()*9,weight:.85+random()*.3}));
function hillField(x,z){let value=0;for(const h of hills){let dx=(x-h.x)/h.rx,dz=(z-h.z)/h.rz;let r=Math.sqrt(dx*dx+dz*dz);let ridge=1+.10*Math.sin(x*.25+z*.12+h.phase)+.07*Math.cos(z*.29-x*.14+h.phase);value=Math.max(value,Math.exp(-.5*r*r)*h.height*ridge)}return value}
function waterScore(x,z){let val=-1e6;if(mode!==1){val=1-Math.abs(x-line(z))/(mode===0?4.8:3.5);for(const branch of branches){let side=branch.side,dx=(x-line(branch.z))*side,progress=Math.max(0,Math.min(1,dx/branch.length));let branchZ=branch.z+progress*(10+4*Math.sin(branch.wave))+2*Math.sin(progress*3+branch.wave)*progress;let inRange=dx>=-1&&dx<=branch.length;let d=Math.abs(z-branchZ);if(inRange)val=Math.max(val,1-d/(1.35*(1-progress*.35)))}}for(const l of lakes){let dx=x-l.x,dz=z-l.z,c=Math.cos(l.angle),s=Math.sin(l.angle),u=(c*dx-s*dz)/l.rx,v=(s*dx+c*dz)/l.rz,a=Math.atan2(v,u),edge=1+.10*Math.sin(a*3+l.phase)+.05*Math.cos(a*5-l.phase);val=Math.max(val,(mode===3?1.25:1)-Math.hypot(u,v)/edge)}return val}
function forestField(x,z){let value=0;for(const f of forestCenters){let dx=(x-f.x)/f.rx,dz=(z-f.z)/f.rz;value=Math.max(value,f.weight*Math.exp(-.5*(dx*dx+dz*dz)))}return value+.06*Math.sin(x*.21+Math.sin(z*.09))+.035*Math.cos(z*.29+x*.15)}
let tiles=new Uint8Array(TOTAL),records=[];for(let z=0;z<N;z++)for(let x=0;x<N;x++){let wx=MIN+x+.5,wz=MIN+z+.5;records.push({i:z*N+x,w:waterScore(wx,wz),h:hillField(wx,wz),f:forestField(wx,wz)})}
const rank=(key,count,type)=>{let candidates=records.filter(r=>tiles[r.i]===0).sort((a,b)=>b[key]-a[key]||a.i-b.i);for(let i=0;i<count;i++)tiles[candidates[i].i]=type};rank('w',781,WATER);rank('h',781,HILL);rank('f',5469,FOREST);
let waterThreshold=Math.min(...records.filter(r=>tiles[r.i]===WATER).map(r=>r.w));let sortedH=records.filter(r=>tiles[r.i]===HILL).map(r=>r.h).sort((a,b)=>a-b),threshold=sortedH[0];function typeAt(x,z){let ix=Math.floor(x)-MIN,iz=Math.floor(z)-MIN;return ix<0||iz<0||ix>=N||iz>=N?0:tiles[iz*N+ix]}
function waterBlend(x,z){let ix=Math.floor(x-.5),iz=Math.floor(z-.5),fx=x-.5-ix,fz=z-.5-iz;let a=typeAt(ix,iz)===WATER?1:0,b=typeAt(ix+1,iz)===WATER?1:0,c=typeAt(ix,iz+1)===WATER?1:0,d=typeAt(ix+1,iz+1)===WATER?1:0;return (a*(1-fx)+b*fx)*(1-fz)+(c*(1-fx)+d*fx)*fz}
